pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        address[] memory governables = new address[](1);
        governables[0] = user;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        bool okRef;
        vm.prank(user);
        try c.assertGovernanceApproved(user, address(0x5678), false) {
            okRef = true;
        } catch {
            okRef = false;
        }
        bool governedFlagRef = c.governed(user);
        assertTrue(governedFlagRef, "User should be governed in reference, but not in bug");
    }
}
